parameters.query:
-- Delete all chapter analysis issues
DELETE FROM manuscript_issues 
WHERE manuscript_id = $1;

-- Return count of deleted issues
SELECT 'issues_deleted' as step;

-- Delete all chapters
DELETE FROM chapters 
WHERE manuscript_id = $1;

SELECT 'chapters_deleted' as step;

-- Delete all chat history
DELETE FROM editor_chat_history 
WHERE manuscript_id = $1;

SELECT 'chat_deleted' as step;

-- Delete all version snapshots
DELETE FROM manuscript_versions 
WHERE manuscript_id = $1;

SELECT 'versions_deleted' as step;

parameters.responseBody:
={
  "success": true,
  "manuscriptId": "{{ $('Webhook').first().json.body.manuscriptId }}",
  "message": "Manuscript cleanup and update complete",
  "timestamp": "{{ new Date().toISOString() }}"
}

